void ui_ScreenSmsWritePhoneNumFind_screen_focus(lv_obj_t * win,void * p_param)
{
    lv_obj_t *      ui_ScreenSmsWritePhoneNumFind = NULL;

    ui_ScreenSmsWritePhoneNumFind = lv_obj_get_user_data(win);

    lv_disp_load_scr(ui_ScreenSmsWritePhoneNumFind);

    {
        lv_obj_t *      list = get_sms_write_phone_num_find_select_list_obj(ui_ScreenSmsWritePhoneNumFind);

        ;
        uint32_t        child_cnt = lv_obj_get_child_cnt(list);
        uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
        lv_obj_t *      get_focus_obj = NULL;
        lv_obj_t *      label;

        get_focus_obj       = lv_obj_get_child(list,child_id);

        if (get_focus_obj) {
            label               = lv_obj_get_child(get_focus_obj,0);
            app_fp_play_tts_menu(lv_label_get_text(label));

#ifdef UI_DISPLAY_SPEED
            ui_screen_sms_write_phone_num_find_select_obj_t * p_screen_param;

            p_screen_param      =
                 (ui_screen_sms_write_phone_num_find_select_obj_t *) lv_obj_get_user_data(ui_ScreenSmsWritePhoneNumFind);

            uint32_t        per =
                 (p_screen_param->list_first_index + child_id) * (100) / (p_screen_param->phonebook_count - 1);

            per                 = per * (100 - p_screen_param->bar_high) / 100;
            per                 = 100 - per;

            lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);
            lv_bar_set_start_value(p_screen_param->bar,per - p_screen_param->bar_high,LV_ANIM_OFF);
            lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);
#endif
            }
        }

}


void sms_write_phone_num_find_select_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_sms_write_phone_num_find_select_obj_t * p_screen_param;
    lv_obj_t *      list = get_sms_write_phone_num_find_select_list_obj(ui_Screen);

    ;
    uint32_t        child_cnt = lv_obj_get_child_cnt(list);
    uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;
    lv_obj_t *      label;

    p_screen_param      = (ui_screen_sms_write_phone_num_find_select_obj_t *) lv_obj_get_user_data(ui_Screen);

    switch (key)
    {
#ifndef UI_DISPLAY_SPEED
        case LV_KEY_UP:
            {
                //__inf("LV_KEY_UP,child_id:%d,child_cnt:%d\r\n",child_id,child_cnt);
                if (child_cnt <= 1)
                    return;

                if (child_id != 0) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);


                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(get_focus_obj,0);
                app_fp_play_tts_menu(lv_label_get_text(label));
                }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != child_cnt - 1) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,0);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(get_focus_obj,0);
                app_fp_play_tts_menu(lv_label_get_text(label));
                }
            break;

#else

        case LV_KEY_UP:
            {
                if (child_cnt <= 1)
                    return;

                pre_focus_obj       = lv_obj_get_child(list,child_id);
                lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                if (child_id != 0) {
                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    phonebook_map_node_t * p_cur_node;

                    get_focus_obj       = lv_obj_get_child(list,child_id);
                    p_cur_node          = lv_obj_get_user_data(get_focus_obj);

                    if (p_cur_node == get_phonebook_head_node()) {
                        p_cur_node          = get_phonebook_prev_count_node(get_phonebook_tail_node(),
                            PHONE_LIST_COUNT - 1);

                        if (p_cur_node == NULL)
                            p_cur_node = get_phonebook_head_node();

                        ui_screen_sms_wirte_find_phone_list_create(p_screen_param->obj_list,p_cur_node);

                        child_cnt           = lv_obj_get_child_cnt(list);

                        if (p_screen_param->phonebook_count > child_cnt)
                            p_screen_param->list_first_index = p_screen_param->phonebook_count - child_cnt;

                        pre_focus_obj       = lv_obj_get_child(list,0);
                        get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        }
                    else {
                        get_focus_obj       = lv_obj_get_child(list,0);
                        p_cur_node          = lv_obj_get_user_data(get_focus_obj);
                        p_cur_node          = get_phonebook_prev_node(p_cur_node);
                        ui_screen_sms_wirte_find_phone_list_create(p_screen_param->obj_list,p_cur_node);

                        if (p_screen_param->list_first_index > 0)
                            p_screen_param->list_first_index--;

                        pre_focus_obj       = lv_obj_get_child(list,1);
                        get_focus_obj       = lv_obj_get_child(list,0);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        child_cnt           = lv_obj_get_child_cnt(list);

                        }
                    }

                label               = lv_obj_get_child(pre_focus_obj,0);
                lv_label_set_long_mode(label,LV_LABEL_LONG_CLIP);

                label               = lv_obj_get_child(get_focus_obj,0);
                lv_label_set_long_mode(label,LV_LABEL_LONG_SCROLL);

                child_id            = get_list_child_focused_id(list,child_cnt);

                uint32_t        per =
                     (p_screen_param->list_first_index + child_id) * (100) / (p_screen_param->phonebook_count - 1);

                per                 = per * (100 - p_screen_param->bar_high) / 100;
                per                 = 100 - per;

                lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);
                lv_bar_set_start_value(p_screen_param->bar,per - p_screen_param->bar_high,LV_ANIM_OFF);
                lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);


                app_fp_play_tts_phonebook(lv_label_get_text(label));
                }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                pre_focus_obj       = lv_obj_get_child(list,child_id);
                lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                if (child_id != child_cnt - 1) {
                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    phonebook_map_node_t * p_cur_node;

                    get_focus_obj       = lv_obj_get_child(list,child_id);
                    p_cur_node          = lv_obj_get_user_data(get_focus_obj);

                    if (p_cur_node == get_phonebook_tail_node()) {
                        p_cur_node          = get_phonebook_head_node();
                        ui_screen_sms_wirte_find_phone_list_create(p_screen_param->obj_list,p_cur_node);
                        p_screen_param->list_first_index = 0;

                        pre_focus_obj       = lv_obj_get_child(list,1);
                        get_focus_obj       = lv_obj_get_child(list,0);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        child_cnt           = lv_obj_get_child_cnt(list);
                        }
                    else {
                        get_focus_obj       = lv_obj_get_child(list,1);
                        p_cur_node          = lv_obj_get_user_data(get_focus_obj);
                        ui_screen_sms_wirte_find_phone_list_create(p_screen_param->obj_list,p_cur_node);

                        if (p_screen_param->list_first_index < p_screen_param->phonebook_count)
                            p_screen_param->list_first_index++;

                        child_cnt           = lv_obj_get_child_cnt(list);
                        pre_focus_obj       = lv_obj_get_child(list,child_cnt - 2);
                        get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        }
                    }

                label               = lv_obj_get_child(pre_focus_obj,0);
                lv_label_set_long_mode(label,LV_LABEL_LONG_CLIP);

                label               = lv_obj_get_child(get_focus_obj,0);
                lv_label_set_long_mode(label,LV_LABEL_LONG_SCROLL);

                child_id            = get_list_child_focused_id(list,child_cnt);

                uint32_t        per =
                     (p_screen_param->list_first_index + child_id) * (100) / (p_screen_param->phonebook_count - 1);

                per                 = per * (100 - p_screen_param->bar_high) / 100;
                per                 = 100 - per;

                lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);
                lv_bar_set_start_value(p_screen_param->bar,per - p_screen_param->bar_high,LV_ANIM_OFF);
                lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);



                app_fp_play_tts_phonebook(lv_label_get_text(label));

                }
            break;

#endif

        case APP_KEY_VALUE_TOP_LEFT:
        case LV_KEY_ENTER:
            {

                void *          p_node;
                phonebook_param_t phonebook_param;

                if (p_screen_param->phonebook_count == 0)
                    return;

                get_focus_obj       = lv_obj_get_child(list,child_id);
                p_node              = (void *) lv_obj_get_user_data(get_focus_obj);

                read_phonebook_param_storge(p_node,&phonebook_param);

                strncpy(p_screen_param->enter_param.p_number,phonebook_param.number,TS_SMS_NUM_MAX_LEN);
                strncpy(p_screen_param->enter_param.p_name,phonebook_param.name,PHONEBOOK_NAME_LEN);

                alv_am_win_exit_current(NULL);

                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);
                }
            break;

        case LV_KEY_END:
            {
                alv_am_app_exit_action_all();
                }

        default:
            break;
        }

}


